async function openFiles(fileList,{insertAt=null,replace=false}={}){const files=[...fileList].filter(f=>f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'));if(!files.length){toast('Bitte eine PDF-Datei auswählen.');return}const loaded=[],importedPages=[];for(const file of files){try{const bytes=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjsLib.getDocument({...pdfjsOptions,data:bytes.slice()}).promise;const pageSizes=await readPageSizes(pdf);const sourceId=`source-${state.nextId++}`;loaded.push({id:sourceId,name:file.name,bytes,pdf,pageSizes});pageSizes.forEach((size,i)=>importedPages.push({id:state.nextId++,sourceId,pageIndex:i,rotation:size.rotate}));status(`${file.name} lokal geöffnet.`)}catch(error){console.error('PDF konnte nicht geöffnet werden',error);toast(`„${file.name}“ konnte nicht geöffnet werden. Prüfe, ob die Datei beschädigt oder geschützt ist.`)}}if(!importedPages.length)return;if(replace)resetDocument();else if(state.pages.length)recordHistory();const offset=documentSources().length;loaded.forEach((source,i)=>{const palette=sourcePalette[(offset+i)%sourcePalette.length];state.sources.set(source.id,{...source,color:palette.color,tint:palette.tint})});const wasEmpty=!state.pages.length;state.pages=insertPages(state.pages,importedPages,insertAt);state.selected=new Set([importedPages[0].id]);state.activePageId=importedPages[0].id;state.anchor=importedPages[0].id;if(wasEmpty&&isCollapsed())toggleSidebar();else renderPageList();await renderViewer();updateControls();if(replace)status(`${loaded.map(s=>s.name).join(' + ')} geöffnet – ${pagesLabel(importedPages.length)}.`);else{status(`${pagesLabel(importedPages.length)} aus ${loaded.length} PDF(s) eingefügt. Noch nicht exportiert.`);toast(loaded.length>1?`${loaded.length} PDFs eingefügt.`:`„${loaded[0].name}“ eingefügt.`)}}
