function selectPage(id,event={}){if(!state.pages.some(p=>p.id===id))return;if(event.shiftKey&&state.anchor!==null){const a=state.pages.findIndex(p=>p.id===state.anchor),b=state.pages.findIndex(p=>p.id===id);state.selected.clear();state.pages.slice(Math.min(a,b),Math.max(a,b)+1).forEach(p=>state.selected.add(p.id))}else if(event.ctrlKey||event.metaKey){state.selected.has(id)?state.selected.delete(id):state.selected.add(id);state.anchor=id}else{state.selected.clear();state.selected.add(id);state.anchor=id}state.activePageId=id;renderPageList();if(editing())renderViewer();else scrollReaderTo(id)}
