const welcomeHtml='<div class="welcome"><div class="welcome-symbol">PDF</div><h2>Deine Dokumente. Deine Kontrolle.</h2><p>PDFs lesen, Seiten sortieren und bearbeiten – direkt in deinem Browser.</p><label class="button primary large" for="pdf-input">PDF-Datei auswählen</label><div class="welcome-notes"><span>✓ Keine Uploads</span><span>✓ Kein Konto</span><span>✓ Lokal verarbeitet</span></div></div>';
