function renderReader(viewer){const frac=readerAnchor();const previous=new Map([...viewer.querySelectorAll('.reader-page')].map(el=>[`${el.dataset.id}|${el.dataset.key}`,el.querySelector('canvas')]));const edit=editing(),spread=state.spread&&!edit;const list=edit?[currentPage()]:state.pages;const rows=pageRows(list.length,spread).map(row=>row.map(i=>list[i]));const cs=getComputedStyle(viewer);const area={width:Math.max(120,viewer.clientWidth-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight)-2),height:Math.max(120,viewer.clientHeight-parseFloat(cs.paddingTop)-parseFloat(cs.paddingBottom)-2)};if(state.fit)state.zoom=fitZoom(state.fit,rows.map(row=>row.map(pageDims)),area,viewGap);const scale=state.zoom*CSS_UNITS;const numbers=new Map(state.pages.map((p,i)=>[p.id,i+1]));const pages=[];const content=document.createElement('div');content.className='viewer-content';for(const row of rows){const els=row.map(p=>{const {width,height}=pageDims(p);const wrap=document.createElement('div');wrap.className='pdf-page reader-page';wrap.dataset.id=String(p.id);wrap.dataset.key=thumbKey(p);wrap.dataset.scale=String(scale);wrap.style.width=`${width*scale}px`;wrap.style.height=`${height*scale}px`;wrap.setAttribute('aria-label',`Seite ${numbers.get(p.id)}`);const canvas=previous.get(`${wrap.dataset.id}|${wrap.dataset.key}`);if(canvas)wrap.append(canvas);wrap._map=pageMap(p,scale);wrap.append(...markLayers(p,wrap._map,true));pages.push(wrap);return wrap});if(spread){const line=document.createElement('div');line.className='reader-row';line.append(...els);content.append(line)}else content.append(...els)}viewer.replaceChildren(content);readerObserver=new IntersectionObserver(entries=>{for(const entry of entries)entry.isIntersecting?drawReaderPage(entry.target):clearReaderPage(entry.target)},{root:viewer,rootMargin:'150% 0px'});pages.forEach(el=>readerObserver.observe(el));if(list[0])scrollReaderTo(edit?list[0].id:currentPage().id,frac);updateControls()}
