async function exportPdf(useSelection=false){if(state.exporting||!state.pages.length)return;const picker=typeof window.showSaveFilePicker==='function';const choice=await askExport(useSelection||state.selected.size>1?'pages':'all',!picker);if(!choice){status('Export abgebrochen.');return}const whole=isWholeDocument(choice.indices);const pages=choice.indices.map(i=>state.pages[i]);let handle=null,fileName=choice.name;if(picker){handle=await pickSaveHandle(suggestedFileName(choice.indices));if(!handle){status('Export abgebrochen.');return}if(handle.fallbackName){fileName=handle.fallbackName;handle=null}}state.exporting=true;updateControls();showProgress(0);status('PDF wird lokal erstellt …');try{const bytes=await buildPdf(pages,id=>state.sources.get(id).bytes,async({phase,done,total})=>{if(phase==='copy'){showProgress(done/total);status(`PDF wird lokal erstellt … ${done} von ${pagesLabel(total)} übernommen`)}else{showProgress(null);status('PDF-Datei wird geschrieben …')}await nextTick()});if(handle){const writable=await handle.createWritable();try{await writable.write(bytes);await writable.close()}catch(error){await writable.abort().catch(()=>{});throw error}fileName=handle.name;toast(`„${fileName}“ gespeichert.`)}else{const blob=new Blob([bytes],{type:'application/pdf'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=fileName;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast(`„${fileName}“ erstellt, Download gestartet.`)}if(whole)state.dirty=false;status(`Export abgeschlossen: ${pagesLabel(pages.length)} → ${fileName}`)}catch(error){console.error('PDF-Export fehlgeschlagen',error);status('Export fehlgeschlagen – es wurde keine Datei gespeichert.');toast('Export fehlgeschlagen. Die Originaldateien blieben unverändert.')}finally{state.exporting=false;showProgress(false);updateControls()}}
