// Context menu: right click (mouse), context-menu key / Shift+F10, or long press and release (touch/pen). Uses the same operations as toolbar and keyboard.
const contextMenu=$('context-menu');
function menuItems(){const sel=state.selected.size>0;return [{label:'Kopieren',keys:'Strg+C',run:copyPages,enabled:sel},{label:'Ausschneiden',keys:'Strg+X',run:cutPages,enabled:sel},{label:'Dahinter einfügen',keys:'Strg+V',run:pastePages,enabled:state.clipboard.length>0},{label:'Duplizieren',keys:'Strg+D',run:duplicateSelected,enabled:sel},null,{label:'Links drehen',run:()=>rotateSelected(-90),enabled:sel},{label:'Rechts drehen',run:()=>rotateSelected(90),enabled:sel},{label:'Leere Seite dahinter',run:insertBlankPage,enabled:true},null,{label:'Auswahl exportieren …',keys:'Strg+Shift+S',run:()=>exportPdf(true),enabled:sel&&!state.exporting},null,{label:'Löschen',keys:'Entf',run:()=>deleteSelected(),enabled:sel,danger:true}]}
function openContextMenu(x,y){contextMenu.replaceChildren();const n=state.selected.size;const header=document.createElement('div');header.className='menu-header';header.textContent=n===1?`Seite ${state.pages.findIndex(p=>state.selected.has(p.id))+1}`:`${n} Seiten ausgewählt`;contextMenu.append(header);for(const item of menuItems()){if(!item){const sep=document.createElement('div');sep.className='menu-sep';sep.setAttribute('role','separator');contextMenu.append(sep);continue}const button=document.createElement('button');button.type='button';button.className='menu-item'+(item.danger?' danger':'');button.setAttribute('role','menuitem');button.disabled=!item.enabled;const label=document.createElement('span');label.textContent=item.label;button.append(label);if(item.keys){const keys=document.createElement('span');keys.className='menu-keys';keys.textContent=item.keys;button.append(keys)}button.addEventListener('click',()=>{closeContextMenu();item.run()});contextMenu.append(button)}contextMenu.hidden=false;const r=contextMenu.getBoundingClientRect();const left=Math.max(8,Math.min(x,innerWidth-r.width-8));const top=y+r.height>innerHeight-8?Math.max(8,y-r.height):y;contextMenu.style.left=`${left}px`;contextMenu.style.top=`${top}px`;contextMenu.querySelector('.menu-item:not(:disabled)')?.focus({preventScroll:true})}
