function openCardMenu(id,point){if(!state.selected.has(id))selectPage(id);const r=pageList.querySelector(`.page-card[data-id="${id}"]`)?.getBoundingClientRect();openContextMenu(point?point.x:r?r.left+r.width/2:0,point?point.y:r?r.top+r.height/2:0)}
function handleMenuKey(e){const items=[...contextMenu.querySelectorAll('.menu-item:not(:disabled)')];const i=items.indexOf(document.activeElement);if(e.key==='Escape'||e.key==='Tab'){e.preventDefault();closeContextMenu(true)}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const down=e.key==='ArrowDown';items[i<0?(down?0:items.length-1):(i+(down?1:-1)+items.length)%items.length]?.focus()}else if(e.key==='Home'||e.key==='End'){e.preventDefault();(e.key==='Home'?items[0]:items.at(-1))?.focus()}}
