window.addEventListener('keydown',e=>{if(!contextMenu.hidden){handleMenuKey(e);return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='f'&&state.pages.length&&!$('export-dialog').open){e.preventDefault();openSearch();return}const typing=e.target instanceof HTMLElement&&(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable);if(typing||$('export-dialog').open)return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase(),edit=editing();if(edit&&state.markSel&&!mod&&(e.key==='Delete'||e.key==='Backspace')){e.preventDefault();deleteSelectedMark();return}if(edit&&mod&&key==='z'&&!e.shiftKey){e.preventDefault();undo()}else if(edit&&((mod&&key==='y')||(mod&&e.shiftKey&&key==='z'))){e.preventDefault();redo()}else if(mod&&key==='o'){e.preventDefault();$('pdf-input').click()}else if(mod&&key==='s'){e.preventDefault();exportPdf(e.shiftKey)}else if(mod&&key==='a'){e.preventDefault();selectAll()}else if(edit&&mod&&key==='c'){e.preventDefault();copyPages()}else if(edit&&mod&&key==='x'){e.preventDefault();cutPages()}else if(edit&&mod&&key==='v'){e.preventDefault();pastePages()}else if(edit&&mod&&key==='d'){e.preventDefault();duplicateSelected()}else if(edit&&e.key==='Delete'&&state.selected.size){e.preventDefault();deleteSelected()}else if(e.key==='Escape'){if(searchOpen()){closeSearch();return}if(state.markSel){selectMark(null);return}if(state.tool){cancelInk();setTool(null);status('Werkzeug beendet.');return}if(state.focus){setFocus(false);return}state.selected.clear();if(state.activePageId)state.selected.add(state.activePageId);renderPageList()}else if(mod&&(e.key==='+'||e.key==='=')){e.preventDefault();zoomBy(1)}else if(mod&&e.key==='-'){e.preventDefault();zoomBy(-1)}else if(mod&&e.key==='0'){e.preventDefault();setFit('auto')}else if(!mod&&!e.altKey&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)&&state.pages.length&&e.target!==$('sidebar-resizer')){e.preventDefault();stepActive(e.key,e.shiftKey)}});
