function styleContext(){const found=state.tool==='select'?selectedMark():null;if(found)return {found,marker:isHighlight(found.mark),color:found.mark.color,width:found.mark.width};const marker=state.tool==='marker';const style=styleFor(state.tool);return {found:null,marker,color:style.color,width:style.width}}
function renderStyleOptions(){const ctx=styleContext();const colors=ctx.marker?MARKER_COLORS:PEN_COLORS,widths=ctx.marker?MARKER_WIDTHS:PEN_WIDTHS;const what=ctx.marker?'Textmarker':ctx.found?'Element':'Stift und Formen';$('pen-colors').setAttribute('aria-label',`Farbe (${what})`);$('pen-colors').replaceChildren(...colors.map(({color,label})=>{const b=document.createElement('button');b.type='button';b.className='swatch';b.style.setProperty('--swatch',color);b.title=`Farbe ${label} (${what})`;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(color===ctx.color));b.addEventListener('click',()=>applyStyle({color}));return b}));$('pen-widths').replaceChildren(...widths.map(({width,label})=>{const b=document.createElement('button');b.type='button';b.className='width-button';b.title=`${ctx.marker?'Breite':'Strichstärke'} ${label} (${what})`;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(width===ctx.width));b.innerHTML=`<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M4 16c4-8 8 4 16-6" fill="none" stroke="currentColor" stroke-linecap="round" stroke-width="${Math.min(9,ctx.marker?width/2.2:width*1.2)}"/></svg>`;b.addEventListener('click',()=>applyStyle({width}));return b}));$('draw-delete').disabled=!ctx.found}
function applyStyle(change){const ctx=styleContext();if(ctx.found){replaceMark(ctx.found.record,ctx.found.mark.id,{...ctx.found.mark,...change});renderStyleOptions();status('Element geändert.');return}Object.assign(styleFor(ctx.marker?'marker':'pen'),change);if(!['pen','marker',...SHAPE_TYPES].includes(state.tool))chooseTool('pen');else renderStyleOptions()}
function viewPoint(wrap,e){const r=wrap.getBoundingClientRect(),map=wrap._map;return [(e.clientX-r.left)*map.width/r.width,(e.clientY-r.top)*map.height/r.height]}
// Top-most mark under a view point: strokes and shapes before highlighter strokes, later before earlier; the selected element can also be grabbed inside its frame.
function markAt(record,wrap,view){const map=wrap._map,[x,y]=map.toPdf(...view),marks=record.marks||[];const sel=state.markSel?.pageId===record.id&&marks.find(m=>m.id===state.markSel.markId);if(sel){const b=markBounds(sel),pad=6/map.scale;if(x>=b.x0-pad&&x<=b.x1+pad&&y>=b.y0-pad&&y<=b.y1+pad)return sel}const order=[...marks.filter(m=>!isHighlight(m)).reverse(),...marks.filter(isHighlight).reverse()];return order.find(m=>markHit(m,x,y,6/map.scale))||null}
function eraseAt(view){const map=drawGesture.wrap._map,record=drawGesture.record;const [x,y]=map.toPdf(...view);const hits=(record.marks||[]).filter(m=>markHit(m,x,y,8/map.scale));if(!hits.length)return;if(!drawGesture.changed)recordHistory();drawGesture.changed=true;record.marks=record.marks.filter(m=>!hits.includes(m));refreshMarks(record)}
function shapeMark(type,start,end,map){return {id:0,type,color:state.pen.color,width:state.pen.width,points:[...map.toPdf(...start),...map.toPdf(...end)].map(roundPoint)}}
function gestureMove(e){const g=drawGesture,map=g.wrap._map;const events=e.type==='pointermove'&&e.getCoalescedEvents?.().length?e.getCoalescedEvents():[e];if(g.tool==='eraser'){for(const ev of events){const pt=viewPoint(g.wrap,ev),from=g.last||pt,steps=Math.max(1,Math.ceil(Math.hypot(pt[0]-from[0],pt[1]-from[1])/4));for(let i=1;i<=steps;i++)eraseAt([from[0]+(pt[0]-from[0])*i/steps,from[1]+(pt[1]-from[1])*i/steps]);g.last=pt}return}const pt=viewPoint(g.wrap,e);if(g.tool==='pen'||g.tool==='marker'){for(const ev of events){const p=viewPoint(g.wrap,ev),last=g.points.at(-1);if(!last||Math.hypot(p[0]-last[0],p[1]-last[1])>=1)g.points.push(p)}const d=g.points.map(([x,y],i)=>`${i?'L':'M'}${x} ${y}`).join('');g.preview.setAttribute('d',g.points.length===1?`${d}L${g.points[0][0]} ${g.points[0][1]}`:d);return}if(g.tool==='select'){const [ax,ay]=map.toPdf(...g.start),[bx,by]=map.toPdf(...pt);g.dx=bx-ax;g.dy=by-ay;g.moved=g.moved||Math.hypot(pt[0]-g.start[0],pt[1]-g.start[1])>2;if(g.moved)refreshMarks(g.record,g.record.marks.map(m=>m.id===g.mark.id?moveMark(m,g.dx,g.dy):m));return}g.end=e.shiftKey?constrainEnd(g.tool,g.start,pt):pt;refreshMarks(g.record,[...(g.record.marks||[]),shapeMark(g.tool,g.start,g.end,map)])}
function cancelInk(){if(!drawGesture)return;const g=drawGesture;drawGesture=null;g.preview?.remove();if(g.tool!=='eraser')refreshMarks(g.record)}
function finishGesture(){const g=drawGesture;drawGesture=null;g.preview?.remove();const live=state.pages.includes(g.record);if(g.tool==='eraser'){if(g.changed){renderPageList();status('Elemente entfernt. Noch nicht exportiert.')}return}if(!live)return;const map=g.wrap._map;if(g.tool==='select'){if(g.moved){replaceMark(g.record,g.mark.id,moveMark(g.mark,g.dx,g.dy));status('Element verschoben.')}return}let mark=null;if(g.tool==='pen'||g.tool==='marker'){if(!g.points.length)return;const style=styleFor(g.tool);mark={id:state.nextId++,type:'ink',color:style.color,width:style.width,points:g.points.flatMap(pt=>map.toPdf(...pt).map(roundPoint))};if(g.tool==='marker')Object.assign(mark,{opacity:MARKER_OPACITY,blend:'multiply'})}else{if(!g.end||Math.hypot(g.end[0]-g.start[0],g.end[1]-g.start[1])<4){refreshMarks(g.record);return}mark={...shapeMark(g.tool,g.start,g.end,map),id:state.nextId++}}recordHistory();g.record.marks=[...(g.record.marks||[]),mark];refreshMarks(g.record);renderPageList();status('Gezeichnet. Wird beim Export fest in die Seite übernommen.')}
viewerEl.addEventListener('pointerdown',e=>{if(drawGesture&&e.pointerId!==drawGesture.pointerId){cancelInk();return}if(!drawing()||!e.isPrimary||e.button>0)return;const wrap=e.target instanceof Element?e.target.closest('.reader-page'):null;const record=wrap&&state.pages.find(p=>p.id===Number(wrap.dataset.id));if(!record||!wrap._map)return;e.preventDefault();const start=viewPoint(wrap,e);const g={tool:state.tool,pointerId:e.pointerId,wrap,record,start,points:[],changed:false,preview:null};if(g.tool==='select'){const mark=markAt(record,wrap,start);if(!mark){selectMark(null);return}g.mark=mark;if(state.markSel?.markId!==mark.id)selectMark({pageId:record.id,markId:mark.id})}wrap.setPointerCapture(e.pointerId);drawGesture=g;if(g.tool==='pen'||g.tool==='marker'){const style=styleFor(g.tool);const path=document.createElementNS(SVG_NS,'path');path.setAttribute('stroke',style.color);path.setAttribute('stroke-width',String(style.width*wrap._map.scale));if(g.tool==='marker')path.setAttribute('stroke-opacity',String(MARKER_OPACITY));wrap.querySelector(`:scope > .mark-layer.${g.tool==='marker'?'highlights':'strokes'}`)?.append(path);g.preview=path}gestureMove(e)});
viewerEl.addEventListener('pointermove',e=>{if(drawGesture){if(e.pointerId===drawGesture.pointerId)gestureMove(e);return}if(state.tool!=='select'||!drawing())return;const wrap=e.target instanceof Element?e.target.closest('.reader-page'):null;const record=wrap?._map&&state.pages.find(p=>p.id===Number(wrap.dataset.id));if(record)wrap.style.cursor=markAt(record,wrap,viewPoint(wrap,e))?'move':''});
viewerEl.addEventListener('pointerup',e=>{if(drawGesture&&e.pointerId===drawGesture.pointerId)finishGesture()});
viewerEl.addEventListener('pointercancel',e=>{if(drawGesture&&e.pointerId===drawGesture.pointerId){if(drawGesture.tool==='eraser'&&drawGesture.changed)finishGesture();else cancelInk()}});
document.querySelectorAll('#ribbon-draw [data-tool]').forEach(b=>b.addEventListener('click',()=>chooseTool(b.dataset.tool)));
$('draw-undo').addEventListener('click',undo);$('draw-redo').addEventListener('click',redo);$('draw-delete').addEventListener('click',deleteSelectedMark);
renderStyleOptions();
